16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Digits;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Digits(fraction = 0, integer = 10)
50	    @Pattern(regexp = "^[0-9]{10}$", message = "Phone number must be exactly 10 digits")
51	    private String telephone;
52	
53	    @Column(name = "email")
54	    private String email;
55	
56	    @Column(name = "registration_date")
57	    private LocalDate registrationDate;
58	
59	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
60	    private Set<Pet> pets;
61	
62	    public String getAddress() {
63	        return this.address;
64	    }
65	
66	    public void setAddress(String address) {
67	        this.address = address;
68	    }
69	
70	    public String getCity() {
71	        return this.city;
72	    }
73	
74	    public void setCity(String city) {
75	        this.city = city;
76	    }
77	
78	    public String getTelephone() {
79	        return this.telephone;
80	    }
81	
82	    public void setTelephone(String telephone) {
83	        this.telephone = telephone;
84	    }
85	
86	    public String getEmail() {
87	        return this.email;
88	    }
89	
90	    public void setEmail(String email) {
91	        this.email = email;
92	    }
93	
94	    public LocalDate getRegistrationDate() {
95	        return this.registrationDate;
96	    }
97	
98	    public void setRegistrationDate(LocalDate registrationDate) {
99	        this.registrationDate = registrationDate;
100	    }
101	
102	    /**
103	     * The owner's name formatted as {@code "LastName, FirstName"} from the stored names.
104	     *
105	     * @return the formatted display name
106	     */
107	    public String getDisplayName() {
108	        return this.getLastName() + ", " + this.getFirstName();
109	    }
110	
111	    /**
112	     * The owner's initials: the upper-cased first letters of the first and last
113	     * names, dot-separated with a trailing dot (e.g. {@code "J.S."}).
114	     *
115	     * @return the formatted initials
116	     */
117	    public String getInitials() {
118	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
119	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
120	    }
121	
122	    protected Set<Pet> getPetsInternal() {
123	        if (this.pets == null) {
124	            this.pets = new HashSet<>();
125	        }
126	        return this.pets;
127	    }
128	
129	    protected void setPetsInternal(Set<Pet> pets) {
130	        this.pets = pets;
131	    }
132	
133	    public List<Pet> getPets() {
134	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
135	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
136	        return Collections.unmodifiableList(sortedPets);
137	    }
138	
139	    public void setPets(List<Pet> pets) {
140	        this.pets = new HashSet<>(pets);
141	    }
142	
143	    public void addPet(Pet pet) {
144	        getPetsInternal().add(pet);
145	        pet.setOwner(this);
146	    }
147	
148	    /**
149	     * Return the Pet with the given name, or null if none found for this Owner.
150	     *
151	     * @param name to test
152	     * @return true if pet name is already in use
153	     */
154	    public Pet getPet(String name) {
155	        return getPet(name, false);
156	    }
157	
158	    /**
159	     * Return the Pet with the given name, or null if none found for this Owner.
160	     *
161	     * @param name to test
162	     * @return true if pet name is already in use
163	     */
164	    public Pet getPet(String name, boolean ignoreNew) {
165	        name = name.toLowerCase();
166	        for (Pet pet : getPetsInternal()) {
167	            if (!ignoreNew || !pet.isNew()) {
168	                String compName = pet.getName();
169	                compName = compName.toLowerCase();
170	                if (compName.equals(name)) {
171	                    return pet;
172	                }
173	            }
174	        }
175	        return null;
176	    }
177	
178	    public Pet getPet(Integer petId) {
179	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
180	    }
181	
182	    @Override
183	    public String toString() {
184	        return new ToStringCreator(this)
185	
186	            .append("id", this.getId())
187	            .append("new", this.isNew())
188	            .append("lastName", this.getLastName())
189	            .append("firstName", this.getFirstName())
190	            .append("address", this.address)
191	            .append("city", this.city)
192	            .append("telephone", this.telephone)
193	            .append("email", this.email)
194	            .toString();
195	    }
196	}
