17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Locale;
23	import java.util.regex.Pattern;
24	
25	import org.springframework.http.HttpHeaders;
26	import org.springframework.http.HttpStatus;
27	import org.springframework.http.ResponseEntity;
28	import org.springframework.samples.petclinic.mapper.OwnerMapper;
29	import org.springframework.samples.petclinic.mapper.PetMapper;
30	import org.springframework.samples.petclinic.mapper.VisitMapper;
31	import org.springframework.samples.petclinic.model.Owner;
32	import org.springframework.samples.petclinic.model.Pet;
33	import org.springframework.samples.petclinic.model.Visit;
34	import org.springframework.samples.petclinic.rest.api.OwnersApi;
35	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
36	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.PetDto;
38	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
41	import org.springframework.samples.petclinic.service.ClinicService;
42	import org.springframework.security.access.prepost.PreAuthorize;
43	import org.springframework.web.bind.annotation.CrossOrigin;
44	import org.springframework.web.bind.annotation.RequestMapping;
45	import org.springframework.web.bind.annotation.RestController;
46	import org.springframework.web.util.UriComponentsBuilder;
47	
48	import jakarta.transaction.Transactional;
49	
50	/**
51	 * @author Vitaliy Fedoriv
52	 */
53	
54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    /**
60	     * Pattern for a syntactically valid email address: a non-empty local part, an '@', and a
61	     * dotted domain ending in a letters-only label. Applied to the trimmed, lower-cased value.
62	     */
63	    private static final Pattern EMAIL_PATTERN =
64	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
65	
66	    private final ClinicService clinicService;
67	
68	    private final OwnerMapper ownerMapper;
69	
70	    private final PetMapper petMapper;
71	
72	    private final VisitMapper visitMapper;
73	
74	    public OwnerRestControllerV1(ClinicService clinicService,
75	                                 OwnerMapper ownerMapper,
76	                                 PetMapper petMapper,
77	                                 VisitMapper visitMapper) {
78	        this.clinicService = clinicService;
79	        this.ownerMapper = ownerMapper;
80	        this.petMapper = petMapper;
81	        this.visitMapper = visitMapper;
82	    }
83	
84	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
85	    @Override
86	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
87	        Collection<Owner> owners;
88	        if (lastName != null) {
89	            owners = this.clinicService.findOwnerByLastName(lastName);
90	        } else {
91	            owners = this.clinicService.findAllOwners();
92	        }
93	        if (owners.isEmpty()) {
94	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
95	        }
96	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
97	    }
98	
99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
102	        Owner owner = this.clinicService.findOwnerById(ownerId);
103	        if (owner == null) {
104	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
105	        }
106	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
107	    }
108	
109	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
110	    @Override
111	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
112	        HttpHeaders headers = new HttpHeaders();
113	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
114	        String telephone = normalizeTelephone(owner.getTelephone());
115	        if (telephone.length() != 10) {
116	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
117	        }
118	        owner.setTelephone(telephone);
119	        if (owner.getRegistrationDate() == null) {
120	            owner.setRegistrationDate(LocalDate.now());
121	        }
122	        if (owner.getEmail() != null) {
123	            String email = normalizeEmail(owner.getEmail());
124	            if (!EMAIL_PATTERN.matcher(email).matches()) {
125	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
126	            }
127	            owner.setEmail(email);
128	        }
129	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
130	            .anyMatch(existing -> telephone.equals(normalizeTelephone(existing.getTelephone())));
131	        if (telephoneInUse) {
132	            return new ResponseEntity<>(HttpStatus.CONFLICT);
133	        }
134	        this.clinicService.saveOwner(owner);
135	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
136	        headers.setLocation(UriComponentsBuilder.newInstance()
137	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
138	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
139	    }
140	
141	    /**
142	     * Normalizes a telephone number for creation by stripping every non-digit character,
143	     * leaving only the digits. Callers require the result to be exactly 10 digits.
144	     *
145	     * @param telephone the raw telephone value (may be {@code null})
146	     * @return the digits-only telephone (never {@code null})
147	     */
148	    private String normalizeTelephone(String telephone) {
149	        return telephone == null ? "" : telephone.replaceAll("\\D", "");
150	    }
151	
152	    /**
153	     * Normalizes an email address for storage by trimming surrounding whitespace and lower-casing
154	     * it. The result is validated by the caller against {@link #EMAIL_PATTERN}.
155	     *
156	     * @param email the raw email value (must not be {@code null})
157	     * @return the trimmed, lower-cased email
158	     */
159	    private String normalizeEmail(String email) {
160	        return email.trim().toLowerCase(Locale.ROOT);
161	    }
162	
163	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
164	    @Override
165	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
166	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
167	        if (currentOwner == null) {
168	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
169	        }
170	        String email = ownerFieldsDto.getEmail();
171	        if (email != null) {
172	            email = normalizeEmail(email);
173	            if (!EMAIL_PATTERN.matcher(email).matches()) {
174	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
175	            }
176	        }
177	        currentOwner.setAddress(ownerFieldsDto.getAddress());
178	        currentOwner.setCity(ownerFieldsDto.getCity());
179	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
180	        currentOwner.setLastName(ownerFieldsDto.getLastName());
181	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
182	        currentOwner.setEmail(email);
183	        this.clinicService.saveOwner(currentOwner);
184	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
185	    }
186	
187	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
188	    @Transactional
189	    @Override
190	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
191	        Owner owner = this.clinicService.findOwnerById(ownerId);
192	        if (owner == null) {
193	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
194	        }
195	        this.clinicService.deleteOwner(owner);
196	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
197	    }
198	
199	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
200	    @Override
201	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
202	        Owner owner = this.clinicService.findOwnerById(ownerId);
203	        if (owner == null) {
204	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
205	        }
206	        HttpHeaders headers = new HttpHeaders();
207	        Pet pet = petMapper.toPet(petFieldsDto);
208	        owner.setId(ownerId);
209	        pet.setOwner(owner);
210	        pet.getType().setName(null);
211	        this.clinicService.savePet(pet);
212	        PetDto petDto = petMapper.toPetDto(pet);
213	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
214	            .buildAndExpand(pet.getId()).toUri());
215	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
216	    }
217	
218	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
219	    @Override
220	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
221	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
222	        if (currentOwner != null) {
223	            Pet currentPet = this.clinicService.findPetById(petId);
224	            if (currentPet != null) {
225	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
226	                currentPet.setName(petFieldsDto.getName());
227	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
228	                this.clinicService.savePet(currentPet);
229	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
230	            }
231	        }
232	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
233	    }
234	
235	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
236	    @Override
237	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
238	        HttpHeaders headers = new HttpHeaders();
239	        Visit visit = visitMapper.toVisit(visitFieldsDto);
240	        Pet pet = new Pet();
241	        pet.setId(petId);
242	        visit.setPet(pet);
243	        this.clinicService.saveVisit(visit);
244	        VisitDto visitDto = visitMapper.toVisitDto(visit);
245	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
246	            .buildAndExpand(visit.getId()).toUri());
247	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
248	    }
249	
250	
251	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
252	    @Override
253	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
254	        Owner owner = this.clinicService.findOwnerById(ownerId);
255	        if (owner != null) {
256	            Pet pet = owner.getPet(petId);
257	            if (pet != null) {
258	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
259	            }
260	        }
261	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
262	    }
263	}
